120	func computeEndpointDiff(oldCEPs, newCEPs map[string]*types.CiliumEndpoint) (added, updated, removed []*types.CiliumEndpoint) {
121		// Find removed endpoints (in old but not in new)
122		for cepName, oldCEP := range oldCEPs {
123			if _, exists := newCEPs[cepName]; !exists {
124				removed = append(removed, oldCEP)
125			}
126		}
127	
128		// Find new or updated endpoints
129		for cepName, newCEP := range newCEPs {
