131				// New endpoint
132				added = append(added, newCEP)
133			} else if !oldCEP.DeepEqual(newCEP) {
134				// Updated endpoint
135				updated = append(updated, newCEP)
136			}
137		}
138	
139		return added, updated, removed
140	}
